args.content:
package propsp

import (
	"strings"
	"testing"

	"yq/node"
	"yq/settings"
)

// dump renders a node tree in a canonical s-expression-ish form so tests
// can assert on exact structure (kinds, tags, order, null fillers).
func dump(n *node.Node) string {
	if n == nil {
		return "<nil>"
	}
	switch n.Kind {
	case node.DocumentKind:
		if len(n.Content) == 0 {
			return "doc()"
		}
		return "doc(" + dump(n.Content[0]) + ")"
	case node.MappingKind:
		var b strings.Builder
		b.WriteString("{")
		for i := 0; i+1 < len(n.Content); i += 2 {
			if i > 0 {
				b.WriteString(" ")
			}
			b.WriteString(strconv_(n.Content[i].Value))
			b.WriteString("=")
			b.WriteString(dump(n.Content[i+1]))
		}
		b.WriteString("}")
		return b.String()
	case node.SequenceKind:
		var b strings.Builder
		b.WriteString("[")
		for i, el := range n.Content {
			if i > 0 {
				b.WriteString(" ")
			}
			b.WriteString(dump(el))
		}
		b.WriteString("]")
		return b.String()
	default:
		return n.Tag + ":" + strconv_(n.Value)
	}
}

func strconv_(s string) string {
	return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
}

func decodeRoot(t *testing.T, input string) *node.Node {
	t.Helper()
	docs, err := Decode([]byte(input), settings.New())
	if err != nil {
		t.Fatalf("Decode(%q) error: %v", input, err)
	}
	if len(docs) != 1 {
		t.Fatalf("Decode(%q) returned %d docs, want 1", input, len(docs))
	}
	return docs[0]
}

func TestDecode(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  string
	}{
		{"dot nesting", "a.b.c=1\na.b.d=2\n", `doc({"a"={"b"={!!str:"c"=... }}})`},
	}
	_ = cases
}

func TestDecodeBasic(t *testing.T) {
	got := dump(decodeRoot(t, "a.b.c=1\na.b.d=2\n"))
	want := `doc({"a"={"b"={"c"=!!str:"1" "d"=!!str:"2"}}})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeValuesAreStrings(t *testing.T) {
	got := dump(decodeRoot(t, "i=1\nf=1.5\nb=true\nn=null\n"))
	want := `doc({"i"=!!str:"1" "f"=!!str:"1.5" "b"=!!str:"true" "n"=!!str:"null"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeSeparators(t *testing.T) {
	got := dump(decodeRoot(t, "a: 1\nb = 2\nc 3\nd\ne=b=c\nf:b:c\n"))
	want := `doc({"a"=!!str:"1" "b"=!!str:"2" "c"=!!str:"3" "d"=!!str:"" "e"=!!str:"b=c" "f"=!!str:"b:c"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeWhitespace(t *testing.T) {
	// Leading whitespace and whitespace around the separator are skipped;
	// trailing whitespace of the value is kept.
	got := dump(decodeRoot(t, "  a  =  1\nb=trailing  \nc=   \n"))
	want := `doc({"a"=!!str:"1" "b"=!!str:"trailing  " "c"=!!str:""})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeWhitespaceSeparatorValue(t *testing.T) {
	// When whitespace is the separator, the rest of the line is the value.
	got := dump(decodeRoot(t, "a \\\n   b = x\n"))
	want := `doc({"a"=!!str:"b = x"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeCommentsAndBlankLines(t *testing.T) {
	got := dump(decodeRoot(t, "# comment\n! bang\n   # indented\n   ! indented\n\n   \na=1\n"))
	want := `doc({"a"=!!str:"1"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeCommentOnlyIsEmptyMap(t *testing.T) {
	got := dump(decodeRoot(t, "# only\n! comments\n\n"))
	if got != "doc({})" {
		t.Errorf("got %s, want doc({})", got)
	}
}

func TestDecodeEmptyInputIsNull(t *testing.T) {
	docs, err := Decode(nil, settings.New())
	if err != nil {
		t.Fatal(err)
	}
	root := docs[0].Root()
	if root == nil || root.Kind != node.ScalarKind || root.Tag != "!!null" || root.Value != "" {
		t.Errorf("empty input root = %s, want empty !!null scalar", dump(root))
	}
}

func TestDecodeInlineCommentNotSpecial(t *testing.T) {
	got := dump(decodeRoot(t, "a=b # tail\nc=d ! tail\n"))
	want := `doc({"a"=!!str:"b # tail" "c"=!!str:"d ! tail"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEscapes(t *testing.T) {
	got := dump(decodeRoot(t, "k\\:ey=v\\:al\na=\\t\\n\\r\\f\\\\\nb=\\u0041BC\nc=\\q\n"))
	want := `doc({"k:ey"=!!str:"v:al" "a"=!!str:"\t\n\r\f\\" "b"=!!str:"ABC" "c"=!!str:"q"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEscapedSpaceInKey(t *testing.T) {
	got := dump(decodeRoot(t, "a\\ b=c\n"))
	want := `doc({"a b"=!!str:"c"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEscapedEqualsInKey(t *testing.T) {
	got := dump(decodeRoot(t, "a\\=b=c\n"))
	want := `doc({"a=b"=!!str:"c"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEscapedDotStillSplits(t *testing.T) {
	// Keys are unescaped first, then split on ".": \. does NOT protect a dot.
	got := dump(decodeRoot(t, "a\\.b=1\n"))
	want := `doc({"a"={"b"=!!str:"1"}})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeUnicodeEscapeInKey(t *testing.T) {
	got := dump(decodeRoot(t, "\\u0041.b=1\n"))
	want := `doc({"A"={"b"=!!str:"1"}})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeContinuation(t *testing.T) {
	got := dump(decodeRoot(t, "a=line1\\\nline2\nb=one\\\n   two\n"))
	want := `doc({"a"=!!str:"line1line2" "b"=!!str:"onetwo"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEvenBackslashesNoContinuation(t *testing.T) {
	got := dump(decodeRoot(t, "a=one\\\\\ntwo=2\n"))
	want := `doc({"a"=!!str:"one\\" "two"=!!str:"2"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeCRLFAndLoneCR(t *testing.T) {
	got := dump(decodeRoot(t, "a=1\r\nb=2\r\nc=3\rd=4\n"))
	want := `doc({"a"=!!str:"1" "b"=!!str:"2" "c"=!!str:"3" "d"=!!str:"4"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeFormFeedIsWhitespace(t *testing.T) {
	got := dump(decodeRoot(t, "a\fb=1\n"))
	want := `doc({"a"=!!str:"b=1"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeTabIsSeparator(t *testing.T) {
	got := dump(decodeRoot(t, "a\tb=1\n"))
	want := `doc({"a"=!!str:"b=1"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeDuplicateKeys(t *testing.T) {
	// Last value wins, position of first occurrence is kept.
	got := dump(decodeRoot(t, "b=1\na=2\nb=3\n"))
	want := `doc({"b"=!!str:"3" "a"=!!str:"2"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeEmptyPathSegments(t *testing.T) {
	got := dump(decodeRoot(t, "a..b=1\n.a=2\nc.=3\n"))
	want := `doc({"a"={""={"b"=!!str:"1"}} ""={"a"=!!str:"2"} "c"={""=!!str:"3"}})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArrays(t *testing.T) {
	got := dump(decodeRoot(t, "a.0=x\na.1=y\n"))
	want := `doc({"a"=[!!str:"x" !!str:"y"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArraySparse(t *testing.T) {
	got := dump(decodeRoot(t, "a.2=x\n"))
	want := `doc({"a"=[!!null:"null" !!null:"null" !!str:"x"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArrayExtends(t *testing.T) {
	got := dump(decodeRoot(t, "a.0=x\na.3=y\n"))
	want := `doc({"a"=[!!str:"x" !!null:"null" !!null:"null" !!str:"y"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArrayOverwrite(t *testing.T) {
	got := dump(decodeRoot(t, "a.1=x\na.0=y\na.0=z\n"))
	want := `doc({"a"=[!!str:"z" !!str:"x"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArrayLeadingZerosAndSigns(t *testing.T) {
	got := dump(decodeRoot(t, "a.01=x\nb.+1=y\nc.-0=z\n"))
	want := `doc({"a"=[!!null:"null" !!str:"x"] "b"=[!!null:"null" !!str:"y"] "c"=[!!str:"z"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeArrayOfMaps(t *testing.T) {
	got := dump(decodeRoot(t, "a.0.b=x\na.1.b=y\n"))
	want := `doc({"a"=[{"b"=!!str:"x"} {"b"=!!str:"y"}]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeRootNumericKeysStayMap(t *testing.T) {
	got := dump(decodeRoot(t, "0=x\n1=y\n"))
	want := `doc({"0"=!!str:"x" "1"=!!str:"y"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeNumericKeyInExistingMap(t *testing.T) {
	// A numeric segment only creates an array for NEW containers; in an
	// existing map it is a plain string key.
	got := dump(decodeRoot(t, "a.b=y\na.0=x\n"))
	want := `doc({"a"={"b"=!!str:"y" "0"=!!str:"x"}})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeDottedNumberKey(t *testing.T) {
	got := dump(decodeRoot(t, "1.5=x\n"))
	want := `doc({"1"=[!!null:"null" !!null:"null" !!null:"null" !!null:"null" !!null:"null" !!str:"x"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeScalarBlocksDeeperPath(t *testing.T) {
	// Traversing into an existing scalar silently ignores the assignment.
	got := dump(decodeRoot(t, "a.b=1\na.b.c=2\nc=3\nc.d=4\ne.0=x\ne.0.b=y\n"))
	want := `doc({"a"={"b"=!!str:"1"} "c"=!!str:"3" "e"=[!!str:"x"]})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeScalarReplacesContainer(t *testing.T) {
	got := dump(decodeRoot(t, "a.b.c=1\na.b=2\nd.0=x\nd=1\n"))
	want := `doc({"a"={"b"=!!str:"2"} "d"=!!str:"1"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeRawUTF8Preserved(t *testing.T) {
	got := dump(decodeRoot(t, "a=héllo😀\n"))
	want := `doc({"a"=!!str:"héllo😀"})`
	if got != want {
		t.Errorf("got  %s\nwant %s", got, want)
	}
}

func TestDecodeErrors(t *testing.T) {
	cases := []struct {
		input string
		want  string
	}{
		{"a.0=x\na.b=y\n", `cannot index array with 'b' (strconv.ParseInt: parsing "b": invalid syntax)`},
		{"a.1=x\na.b.c=y\n", `cannot index array with 'b' (strconv.ParseInt: parsing "b": invalid syntax)`},
		{"a.-1=x\n", "index [-1] out of range, array size is 0"},
		{"=x\n", `properties: Line 1: "x"`},
		{"= x\n", `properties: Line 1: "x"`},
		{":y\n", `properties: Line 1: "y"`},
		{"=\n", `properties: Line 1: ""`},
		{"  =x\n", `properties: Line 1: "x"`},
		{"a=1\n=b\n", `properties: Line 2: "b"`},
		{"=\\u0041x\n", `properties: Line 1: "Ax"`},
		{"a=\\uZZZZx\n", "properties: Line 1: invalid unicode literal"},
	}
	for _, c := range cases {
		_, err := Decode([]byte(c.input), settings.New())
		if err == nil {
			t.Errorf("Decode(%q): expected error %q, got nil", c.input, c.want)
		} else if err.Error() != c.want {
			t.Errorf("Decode(%q) error = %q, want %q", c.input, err.Error(), c.want)
		}
	}
}

// --- encoder tests ---

func encode(t *testing.T, n *node.Node, mutate func(*settings.Settings)) string {
	t.Helper()
	s := settings.New()
	if mutate != nil {
		mutate(s)
	}
	var b strings.Builder
	if err := Encode(&b, []*node.Node{n}, s); err != nil {
		t.Fatalf("Encode error: %v", err)
	}
	return b.String()
}

// buildMap is a small helper: buildMap("k1", v1, "k2", v2, ...).
func buildMap(pairs ...interface{}) *node.Node {
	m := node.NewMapping()
	for i := 0; i < len(pairs); i += 2 {
		m.Content = append(m.Content, node.NewString(pairs[i].(string)), pairs[i+1].(*node.Node))
	}
	return m
}

func seq(els ...*node.Node) *node.Node {
	s := node.NewSequence()
	s.Content = append(s.Content, els...)
	return s
}

func TestEncodeBasic(t *testing.T) {
	n := buildMap("a", buildMap("b", node.NewScalar("!!int", "1"), "c", node.NewString("x")))
	if got := encode(t, n, nil); got != "a.b = 1\na.c = x\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeSeparatorFlag(t *testing.T) {
	n := buildMap("a", node.NewScalar("!!int", "1"))
	if got := encode(t, n, func(s *settings.Settings) { s.PropsSeparator = "=" }); got != "a=1\n" {
		t.Errorf("got %q", got)
	}
	if got := encode(t, n, func(s *settings.Settings) { s.PropsSeparator = ":" }); got != "a:1\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeArrays(t *testing.T) {
	n := buildMap("a", seq(node.NewScalar("!!int", "1"), node.NewScalar("!!int", "2")))
	if got := encode(t, n, nil); got != "a.0 = 1\na.1 = 2\n" {
		t.Errorf("got %q", got)
	}
	if got := encode(t, n, func(s *settings.Settings) { s.PropsArrayBrackets = true }); got != "a[0] = 1\na[1] = 2\n" {
		t.Errorf("brackets: got %q", got)
	}
}

func TestEncodeNestedArrays(t *testing.T) {
	n := seq(seq(node.NewScalar("!!int", "1"), node.NewScalar("!!int", "2")), seq(node.NewScalar("!!int", "3")))
	if got := encode(t, n, nil); got != "0.0 = 1\n0.1 = 2\n1.0 = 3\n" {
		t.Errorf("got %q", got)
	}
	m := buildMap("a", seq(seq(node.NewScalar("!!int", "1"))))
	if got := encode(t, m, func(s *settings.Settings) { s.PropsArrayBrackets = true }); got != "a[0][0] = 1\n" {
		t.Errorf("brackets: got %q", got)
	}
	// Brackets never apply to the root array itself, but do apply below it.
	if got := encode(t, seq(seq(node.NewScalar("!!int", "1"))), func(s *settings.Settings) { s.PropsArrayBrackets = true }); got != "0[0] = 1\n" {
		t.Errorf("root brackets: got %q", got)
	}
}

func TestEncodeArrayOfMaps(t *testing.T) {
	n := buildMap("a", seq(buildMap("b", node.NewScalar("!!int", "1"))))
	if got := encode(t, n, func(s *settings.Settings) { s.PropsArrayBrackets = true }); got != "a[0].b = 1\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeDeepNesting(t *testing.T) {
	n := buildMap("a", buildMap("b", buildMap("c", node.NewScalar("!!int", "1"))), "d", node.NewScalar("!!int", "2"))
	if got := encode(t, n, nil); got != "a.b.c = 1\nd = 2\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeScalarValuesUseRawText(t *testing.T) {
	n := buildMap(
		"a", node.NewNull(),
		"b", node.NewScalar("!!bool", "true"),
		"c", node.NewScalar("!!float", "1.5"),
		"d", node.NewScalar("!!float", "1.0"),
		"e", node.NewScalar("!!timestamp", "2020-01-01"),
	)
	want := "a = null\nb = true\nc = 1.5\nd = 1.0\ne = 2020-01-01\n"
	if got := encode(t, n, nil); got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestEncodeEmptyContainers(t *testing.T) {
	if got := encode(t, node.NewMapping(), nil); got != "" {
		t.Errorf("empty map: got %q", got)
	}
	if got := encode(t, node.NewSequence(), nil); got != "" {
		t.Errorf("empty seq: got %q", got)
	}
	if got := encode(t, buildMap("a", node.NewMapping()), nil); got != "" {
		t.Errorf("nested empty map: got %q", got)
	}
	if got := encode(t, buildMap("a", node.NewSequence()), nil); got != "" {
		t.Errorf("nested empty seq: got %q", got)
	}
}

func TestEncodeKeyOrderPreserved(t *testing.T) {
	n := buildMap("b", node.NewScalar("!!int", "1"), "a", node.NewScalar("!!int", "2"), "c", node.NewScalar("!!int", "3"))
	if got := encode(t, n, nil); got != "b = 1\na = 2\nc = 3\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeKeyEscapes(t *testing.T) {
	n := buildMap(
		"a:b", node.NewScalar("!!int", "1"),
		"a b", node.NewScalar("!!int", "2"),
		"a=b", node.NewScalar("!!int", "3"),
		"a#b", node.NewScalar("!!int", "4"),
		"a!b", node.NewScalar("!!int", "5"),
		":k", node.NewScalar("!!int", "6"),
		" k", node.NewScalar("!!int", "7"),
		"a\tb", node.NewScalar("!!int", "8"),
		"a\\b", node.NewScalar("!!int", "9"),
		"a\nb", node.NewScalar("!!int", "10"),
	)
	want := "a\\:b = 1\na\\ b = 2\na=b = 3\na#b = 4\na!b = 5\n\\:k = 6\n\\ k = 7\na\\tb = 8\na\\\\b = 9\na\\nb = 10\n"
	if got := encode(t, n, nil); got != want {
		t.Errorf("got  %q\nwant %q", got, want)
	}
}

func TestEncodeDotsInKeysNotEscaped(t *testing.T) {
	n := buildMap("a.b", node.NewScalar("!!int", "1"))
	if got := encode(t, n, nil); got != "a.b = 1\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeValueEscapes(t *testing.T) {
	n := buildMap(
		"a", node.NewString("x\ty"),
		"b", node.NewString("x\ny"),
		"c", node.NewString("x\ry"),
		"d", node.NewString("x\fy"),
		"e", node.NewString("x\\y"),
		"f", node.NewString(" lead"),
		"g", node.NewString("  x"),
		"h", node.NewString("trail "),
		"i", node.NewString("x:y=z"),
		"j", node.NewString("#v"),
		"k", node.NewString("!v"),
		"l", node.NewString(":v"),
		"m", node.NewString("=v"),
		"n", node.NewString("héllo😀"),
		"o", node.NewString(""),
	)
	want := "a = x\\ty\n" +
		"b = x\\ny\n" +
		"c = x\\ry\n" +
		"d = x\\fy\n" +
		"e = x\\\\y\n" +
		"f = \\ lead\n" +
		"g = \\  x\n" +
		"h = trail \n" +
		"i = x:y=z\n" +
		"j = #v\n" +
		"k = !v\n" +
		"l = :v\n" +
		"m = =v\n" +
		"n = héllo😀\n" +
		"o = \n"
	if got := encode(t, n, nil); got != want {
		t.Errorf("got  %q\nwant %q", got, want)
	}
}

func TestEncodeScalarRoot(t *testing.T) {
	// Scalar roots print bare, without any escaping.
	if got := encode(t, node.NewString("scalar"), nil); got != "scalar\n" {
		t.Errorf("got %q", got)
	}
	if got := encode(t, node.NewString(" x"), nil); got != " x\n" {
		t.Errorf("leading space root: got %q", got)
	}
	if got := encode(t, node.NewNull(), nil); got != "null\n" {
		t.Errorf("null root: got %q", got)
	}
	if got := encode(t, node.NewScalar("!!null", ""), nil); got != "\n" {
		t.Errorf("empty null root: got %q", got)
	}
}

func TestEncodeArrayRoot(t *testing.T) {
	n := seq(node.NewScalar("!!int", "1"), node.NewScalar("!!int", "2"))
	if got := encode(t, n, nil); got != "0 = 1\n1 = 2\n" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeMultipleDocs(t *testing.T) {
	s := settings.New()
	var b strings.Builder
	n1 := buildMap("a", node.NewScalar("!!int", "1"))
	n2 := buildMap("b", node.NewScalar("!!int", "2"))
	if err := Encode(&b, []*node.Node{n1, n2}, s); err != nil {
		t.Fatal(err)
	}
	if b.String() != "a = 1\nb = 2\n" {
		t.Errorf("got %q", b.String())
	}
}

func TestEncodeNulOutput(t *testing.T) {
	n := buildMap("a", node.NewScalar("!!int", "1"), "b", node.NewScalar("!!int", "2"))
	got := encode(t, n, func(s *settings.Settings) { s.NulOutput = true })
	if got != "a = 1\nb = 2\x00" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeIgnoresIndentAndUnwrap(t *testing.T) {
	n := buildMap("a", node.NewScalar("!!int", "1"))
	got := encode(t, n, func(s *settings.Settings) {
		s.Indent = 9
		s.UnwrapScalar = false
	})
	if got != "a = 1\n" {
		t.Errorf("got %q", got)
	}
}

// Round trip: properties input decoded and re-encoded byte-identically for
// canonical inputs.
func TestRoundTrip(t *testing.T) {
	input := "a.b = 1\na.c = x\n"
	docs, err := Decode([]byte(input), settings.New())
	if err != nil {
		t.Fatal(err)
	}
	if got := encode(t, docs[0].Root(), nil); got != input {
		t.Errorf("got %q, want %q", got, input)
	}
}

