}

func TestDecodeScalarReplacesContainer(t *testing.T) {
	got := dump(decodeRoot(t, "a.b.c=1\na.b=2\nd.0=x\nd=1\n"))
	want := `doc({"a"={"b"=!!str:"2"} "d"=!!str:"1"})`
